def replace_condition(condition)
  return condition.source unless wrap_condition?(condition)

  if parenthesize_method_arguments?(condition)
    parenthesized_method_arguments(condition)
  else
    "(#{condition.source})"
  end
end

def parenthesize_method_arguments?(node)
  node.call_type? && !node.comparison_method? && !node.operator_method?
end
